// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AttachmentJob) predicate.AttachmentJob {
	return predicate.AttachmentJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AttachmentJob) predicate.AttachmentJob {
	return predicate.AttachmentJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AttachmentJob) predicate.AttachmentJob {
	return predicate.AttachmentJob(sql.NotPredicates(p))
}
